(function(){'use strict';var cfg=window.ocsCfg||{};var chunk=null;var payloads={};var SEEN='ocs_seen';var queue=window.__ocsQ=[];function device(){return window.matchMedia&&matchMedia('(max-width: 781px)').matches?'m':'d';}
function flush(){if(!queue.length||!cfg.events||!navigator.sendBeacon){queue.length=0;return;}
var batch=queue.splice(0,50);for(var i=0;i<batch.length;i++){if(!batch[i].d){batch[i].d=device();}}
navigator.sendBeacon(cfg.events,JSON.stringify(batch));}
function barOf(node){return node.closest?node.closest('[data-ocs-bar]'):null;}
function payload(bar){var key=bar.getAttribute('data-ocs-bar');if(!payloads[key]){var inline=document.getElementById('ocs-data-'+key);payloads[key]=inline?Promise.resolve(JSON.parse(inline.textContent)):fetch(bar.getAttribute('data-ocs-src'),{credentials:'omit'}).then(function(r){return r.json();});}
return payloads[key];}
function warm(bar){if(!bar){return;}
if(!chunk){var link=document.createElement('link');link.rel='stylesheet';link.href=cfg.css;document.head.appendChild(link);chunk=import(new URL(cfg.player,document.baseURI).href).catch(function(e){if(window.console){console.error('OC Story: the player could not be loaded from '+cfg.player,e);}
chunk=null;throw e;});}
payload(bar);}
function seen(){try{return JSON.parse(localStorage.getItem(SEEN)||'{}');}catch(e){return{};}}
function markSeen(id){try{var all=seen();all[id]=1;localStorage.setItem(SEEN,JSON.stringify(all));}catch(e){}
document.querySelectorAll('[data-ocs-open="'+id+'"]').forEach(function(node){node.setAttribute('data-ocs-seen','1');});}
function paintSeen(){var all=seen();Object.keys(all).forEach(function(id){document.querySelectorAll('[data-ocs-open="'+id+'"]').forEach(function(node){node.setAttribute('data-ocs-seen','1');});});}
function openFrom(button){var bar=barOf(button);if(!bar){return;}
warm(bar);var id=parseInt(button.getAttribute('data-ocs-open'),10);Promise.all([chunk,payload(bar)]).then(function(parts){var stories=parts[1]||[];var index=0;for(var i=0;i<stories.length;i++){if(stories[i].i===id){index=i;break;}}
parts[0].open(stories,index,{cfg:cfg,surface:bar.getAttribute('data-ocs-surface')||'',onSeen:markSeen,});}).catch(function(){});}
document.addEventListener('pointerdown',function(e){var button=e.target.closest&&e.target.closest('[data-ocs-open]');if(button){warm(barOf(button));}},{passive:true});document.addEventListener('click',function(e){var button=e.target.closest&&e.target.closest('[data-ocs-open]');if(button){e.preventDefault();openFrom(button);}});if(window.requestIdleCallback){requestIdleCallback(paintSeen);}else{setTimeout(paintSeen,400);}
if(cfg.events&&window.IntersectionObserver){var observer=new IntersectionObserver(function(entries){entries.forEach(function(entry){if(!entry.isIntersecting){return;}
observer.unobserve(entry.target);queue.push({t:'i',s:0,f:entry.target.getAttribute('data-ocs-surface')||'',});});},{threshold:0.4});document.querySelectorAll('[data-ocs-bar]').forEach(function(bar){observer.observe(bar);});}
addEventListener('pagehide',flush);document.addEventListener('visibilitychange',function(){if('hidden'===document.visibilityState){flush();}});}());